export type StoreGroupId =
  | 'amazon'
  | 'aliexpress'
  | 'alibaba'
  | 'ebay'
  | 'noon'
  | 'honor'
  | 'huawei'
  | 'lenovo'
  | 'canon'
  | 'parallels'
  | 'adguard'
  | 'admitad';

export interface StoreBranch {
  id: string;
  groupId: StoreGroupId;
  nameEn: string;
  nameAr: string;
  domain: string;
  currencySymbol: string;
  currencyCode: string;
  currencyAr: string;
  flag: string;
  affiliateUrl: string;
  comingSoon?: boolean;
  /** Default price bracket threshold display note if branch has no SKUs > 10k etc. */
}

export interface StoreGroup {
  id: StoreGroupId;
  nameEn: string;
  nameAr: string;
  defaultStoreId: string;
  branches: StoreBranch[];
  comingSoon?: boolean;
  taglineEn: string;
  taglineAr: string;
}

export type CatalogCategoryId =
  | 'all'
  | 'smartphones'
  | 'laptops'
  | 'tablets-wearables'
  | 'audio'
  | 'tv-monitors'
  | 'men-fashion'
  | 'women-fashion'
  | 'accessories'
  | 'watches-jewelry'
  | 'beauty-health'
  | 'home-furniture'
  | 'food-grocery'
  | 'cars'
  | 'motorcycles'
  | 'software';

export interface CatalogCategory {
  id: CatalogCategoryId;
  group: 'electronics' | 'fashion' | 'home' | 'auto' | 'all';
  nameEn: string;
  nameAr: string;
  homeRowTitleEn: string;
  homeRowTitleAr: string;
}

export type PriceTierId =
  | 'all'
  | '1-30'
  | '30-60'
  | '60-100'
  | '100-150'
  | '150-500'
  | '500-1000'
  | '1000-2000'
  | '2000-3000'
  | '3000-5000'
  | 'over-5000'
  | 'over-10000';

export interface PriceTierMeta {
  id: PriceTierId;
  min: number;
  max: number | null;
  labelEn: (currency: string) => string;
  labelAr: (currencyAr: string) => string;
  isFlashTier?: boolean;
}

export interface CatalogProduct {
  id: string;
  storeId: string;
  storeNameEn: string;
  storeNameAr: string;
  categoryId: CatalogCategoryId;
  brand: string;
  titleEn: string;
  titleAr: string;
  specsEn: string;
  specsAr: string;
  price: string;
  oldPrice?: string;
  numericPrice: number;
  discountPercent: number;
  discountBadgeEn: string;
  discountBadgeAr: string;
  image: string;
  affiliateUrl: string;
  containImage?: boolean;
  isFlashDeal?: boolean;
}

export interface CouponOfferItem {
  id: string;
  storeId: string;
  storeNameEn: string;
  storeNameAr: string;
  type: 'code' | 'bank' | 'event' | 'portal';
  titleEn: string;
  titleAr: string;
  descriptionEn: string;
  descriptionAr: string;
  code?: string | null;
  discountBadgeEn: string;
  discountBadgeAr: string;
  image: string;
  affiliateUrl: string;
}

